/* Persian (فارسی) — builds public/fa/, which runs right to left. See
   build.mjs for how these are used. Each pair is [the English exactly as on
   the page, the Persian]. Polite "شما"; prices stay in dollars with Latin
   digits ($80), as on the calendar and the receipt; other numbers in
   Persian digits. Names of people, clubs and courts stay in Latin letters.
   Words joined with a zero-width non-joiner (می‌خواهم) are meant that way.
   Translated by Claude: worth a read by a native speaker. */

